pseudocode:
let n = S.length; let dp = Array(n + 1).fill(1);
for (let char of S) {
  let next = Array(n + 1).fill(0);
  if (char === 'I') {
    for (let i = 1; i <= n; i++) next[i] = next[i-1] + dp[i-1];
  } else {
    for (let i = n - 1; i >= 0; i--) next[i] = next[i+1] + dp[i+1];
  }
  dp = next; n--;
}
